  def extract(): Map[String, Json] = {
    val entries = Rows.zipWithIndex.map { case (r, i) =>
      val (_, outcome) = EvalCore.evalApplied(r.treeHex, IntInput, activated = 3)
      val where = if (r.kind == "parse") s"`${r.name}` (sigma-rust's ${r.set}), inside `if (true) true else { val v = " +
        "…; false }`" else s"`${r.name}` (sigma-rust's ${r.set}), as written"
      val s = outcome match {
        case Right((v, c)) if r.control => s"$where → built, ${v.noSpaces.take(60)} at cost $c. CONTROL: a call of the " +
          "same method the JVM's substitution parses."
        case Right((v, c)) => s"$where → ${v.noSpaces.take(60)} at cost $c. SEPARATING: an implementation that " +
          "substitutes the explicit type once, or throws where kiama does not, refuses it."
        case Left(err) if r.kind == "parse" => s"$where — REFUSED AT PARSE (`${err.take(140)}`). SEPARATING: an " +
          "implementation that substitutes once, or without kiama's throw, builds it."
        case Left(err) => s"$where — THROWS at evaluation (`${err.take(140)}`)."
      }
      val name = s"${r.set.stripSuffix(".txt")}-${r.name.replaceAll("[^A-Za-z0-9]+", "-").take(60)}#$i"
      if (r.accept) SpecExtract.authoredEntryV(Op, s"[${r.set}|${r.name}] $s", r.treeHex, name, IntInput, 3, ergoTree = 3)
      else SpecExtract.authoredRejectEntryV(Op, s"[${r.set}|${r.name}] $s", r.treeHex, name, IntInput, 3, ergoTree = 3)
    }
    Map(Op -> SpecExtract.authoredEnvelope(Op, entries, Source).mapObject(_.add("blessed_by", Json.fromString(Stamp))))
  }

  def wireExtract(): Json = {
    val entries = Trees.zipWithIndex.map { case ((n, hex), i) =>
      scala.util.Try(WireCanonicalize.canonicalize("ErgoTree", hex, 3, 3)) match {
        case scala.util.Success(out) => sys.error(s"$n: must be REJECTED, round-tripped to $out")
        case scala.util.Failure(t) =>
          val causes = Iterator.iterate(t: Throwable)(_.getCause).takeWhile(_ != null).toSeq
          require(!causes.exists(_.isInstanceOf[sigma.validation.ValidationException]), s"$n: a ValidationException degrades")
      }
      Json.obj("name" -> Json.fromString(s"static-type-${n.replaceAll("[^A-Za-z0-9]+", "-").take(60)}#$i"),
        "kind" -> Json.fromString("ErgoTree"), "source" -> Json.fromString(Source),
        "description" -> Json.fromString(s"[$n] A sized v3 tree whose call meets the explicit type substitution: " +
          "kiama's throw (`dup illegal arguments`), or the node around the call refusing the twice-substituted type " +
          "(`ConstraintFailed`), also where the call sits in a branch never taken — REJECTED: neither is a " +
          "ValidationException, so the size bit does not degrade it. SEPARATING: an implementation that substitutes " +
          "once, or without the throw, accepts the tree."),
        "bytes_hex" -> Json.fromString(hex), "error" -> Json.fromString("errored"),
        "version" -> Json.obj("activated" -> Json.fromInt(3), "ergoTree" -> Json.fromInt(3)))
    }
    Json.obj("schema" -> Json.fromString("santa-wire/v1"), "op" -> Json.fromString(OpWire),
      "blessed_by" -> Json.fromString(Stamp), "entries" -> Json.arr(entries: _*))
  }

  def writeVectors(evalDir: java.nio.file.Path, wireDir: java.nio.file.Path): Unit = {
    SpecExtract.writeStaging("AuthoredMethodCallStaticType.eval", extract(), evalDir)
    SpecExtract.writeStaging("AuthoredMethodCallStaticType.wire", Map(OpWire -> wireExtract()), wireDir)
  }
}
